<div class="avantpedia-container">

<!-- Hero Section with Animated Background -->
<div style="
    position: relative;
    background: linear-gradient(135deg, #0f0f23 0%, #1a1a3e 25%, #2d1b69 50%, #b21f1f 75%, #fdbb2d 100%);
    background-size: 400% 400%;
    animation: gradientShift 8s ease infinite;
    color: white;
    padding: 4em 2em;
    border-radius: 20px;
    margin-bottom: 2em;
    text-align: center;
    box-shadow: 0 20px 40px rgba(0,0,0,0.3), 0 0 100px rgba(253, 187, 45, 0.1);
    overflow: hidden;
">
    <!-- Animated particles background -->
    <div style="
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-image:
            radial-gradient(2px 2px at 20px 30px, rgba(255,255,255,0.3), transparent),
            radial-gradient(2px 2px at 40px 70px, rgba(255,255,255,0.2), transparent),
            radial-gradient(1px 1px at 90px 40px, rgba(255,255,255,0.4), transparent),
            radial-gradient(1px 1px at 130px 80px, rgba(255,255,255,0.2), transparent);
        background-repeat: repeat;
        background-size: 200px 100px;
        animation: sparkle 3s linear infinite;
        pointer-events: none;
    "></div>

    <div style="position: relative; z-index: 2;">
        <h1 style="
            font-size: clamp(2.5em, 5vw, 4em);
            margin-bottom: 0.3em;
            text-shadow: 3px 3px 6px rgba(0,0,0,0.5);
            font-weight: 800;
            letter-spacing: 2px;
            background: linear-gradient(45deg, #ffffff, #fdbb2d, #ffffff);
            background-size: 200% 200%;
            -webkit-background-clip: text;
            -webkit-text-fill-color: transparent;
            animation: textShimmer 3s ease-in-out infinite;
        ">The Avantpedia</h1>

        <div style="
            width: 100px;
            height: 4px;
            background: linear-gradient(90deg, transparent, #fdbb2d, transparent);
            margin: 1em auto;
            border-radius: 2px;
        "></div>

        <p style="
            font-size: clamp(1.1em, 2.5vw, 1.4em);
            max-width: 900px;
            margin: 1.5em auto 0;
            line-height: 1.7;
            text-shadow: 1px 1px 3px rgba(0,0,0,0.3);
            opacity: 0.95;
        ">Documenting the epic story of the <strong>Avant-Garde World & Universe</strong><br>
        Built by dedicated players within our thriving Discord community</p>
    </div>
</div>

<!-- Quick Stats & Navigation Bar -->
<div style="
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: 1.5em;
    margin-bottom: 2em;
">
    <div style="
        background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
        color: white;
        padding: 1.5em;
        border-radius: 15px;
        text-align: center;
        box-shadow: 0 10px 25px rgba(102, 126, 234, 0.3);
        transition: transform 0.3s ease;
    " onmouseover="this.style.transform='translateY(-5px)'" onmouseout="this.style.transform='translateY(0)'">
        <div style="font-size: 2.5em; margin-bottom: 0.2em;">🌍</div>
        <div style="font-size: 1.8em; font-weight: bold; margin-bottom: 0.2em;">17+</div>
        <div style="opacity: 0.9;">Active Nations</div>
    </div>

    <div style="
        background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%);
        color: white;
        padding: 1.5em;
        border-radius: 15px;
        text-align: center;
        box-shadow: 0 10px 25px rgba(240, 147, 251, 0.3);
        transition: transform 0.3s ease;
    " onmouseover="this.style.transform='translateY(-5px)'" onmouseout="this.style.transform='translateY(0)'">
        <div style="font-size: 2.5em; margin-bottom: 0.2em;">🏛️</div>
        <div style="font-size: 1.8em; font-weight: bold; margin-bottom: 0.2em;">7+</div>
        <div style="opacity: 0.9;">Organizations</div>
    </div>

    <div style="
        background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%);
        color: white;
        padding: 1.5em;
        border-radius: 15px;
        text-align: center;
        box-shadow: 0 10px 25px rgba(79, 172, 254, 0.3);
        transition: transform 0.3s ease;
    " onmouseover="this.style.transform='translateY(-5px)'" onmouseout="this.style.transform='translateY(0)'">
        <div style="font-size: 2.5em; margin-bottom: 0.2em;">⚔️</div>
        <div style="font-size: 1.8em; font-weight: bold; margin-bottom: 0.2em;">5+</div>
        <div style="opacity: 0.9;">Years Active</div>
    </div>

    <div style="
        background: linear-gradient(135deg, #fa709a 0%, #fee140 100%);
        color: white;
        padding: 1.5em;
        border-radius: 15px;
        text-align: center;
        box-shadow: 0 10px 25px rgba(250, 112, 154, 0.3);
        transition: transform 0.3s ease;
    " onmouseover="this.style.transform='translateY(-5px)'" onmouseout="this.style.transform='translateY(0)'">
        <div style="font-size: 2.5em; margin-bottom: 0.2em;">📚</div>
        <div style="font-size: 1.8em; font-weight: bold; margin-bottom: 0.2em;">[[Special:Statistics|{{NUMBEROFARTICLES}}]]</div>
        <div style="opacity: 0.9;">Wiki Articles</div>
    </div>
</div>

<!-- About Section with Enhanced Design -->
<div style="
    background: linear-gradient(135deg, #ffffff 0%, #f8f9fa 100%);
    padding: 3em 2em;
    border-radius: 20px;
    box-shadow: 0 15px 35px rgba(0,0,0,0.1);
    margin-bottom: 2em;
    position: relative;
    overflow: hidden;
">
    <!-- Decorative elements -->
    <div style="
        position: absolute;
        top: -50px;
        right: -50px;
        width: 200px;
        height: 200px;
        background: linear-gradient(45deg, rgba(52, 152, 219, 0.1), rgba(46, 204, 113, 0.1));
        border-radius: 50%;
        pointer-events: none;
    "></div>

    <div style="position: relative; z-index: 2;">
        <h2 style="
            text-align: center;
            font-size: 2.5em;
            margin-bottom: 1em;
            color: #2c3e50;
            position: relative;
        ">
            <span style="
                background: linear-gradient(120deg, #3498db, #2ecc71);
                -webkit-background-clip: text;
                -webkit-text-fill-color: transparent;
                font-weight: 700;
            ">About Avant-Garde</span>
        </h2>

        <div style="text-align: center; margin: 2em auto; max-width: 400px;">
            [[File:AV Logo2.png|center|frameless|350x350px|alt=The Avant-Garde RP server logo]]
        </div>

        <div style="
            max-width: 900px;
            margin: 0 auto;
            text-align: center;
            font-size: 1.3em;
            line-height: 1.8;
            color: #34495e;
            margin-bottom: 2em;
        ">
            The <strong>Avant-Garde RP server</strong> represents the pinnacle of collaborative worldbuilding,
            forged by a dedicated community of experienced roleplayers with over <strong>5 years</strong> of
            collective expertise. Our universe continues to evolve daily, with this wiki serving as the
            definitive chronicle of our shared adventures and discoveries.
        </div>

        <!-- Action Buttons -->
        <div style="
            display: flex;
            justify-content: center;
