/* ===== AVANT GARDE WIKI - MODERN TYPOGRAPHY ENHANCEMENTS ===== */
/* Modern font improvements while preserving existing MediaWiki functionality */

/* Import modern fonts */
@import url('https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500&display=swap');

/* Modern typography variables */
:root {
    /* Font families */
    --font-primary: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', sans-serif;
    --font-mono: 'JetBrains Mono', 'SF Mono', 'Monaco', 'Consolas', monospace;

    /* Typography scale */
    --text-xs: 0.75rem;
    --text-sm: 0.875rem;
    --text-base: 1rem;
    --text-lg: 1.125rem;
    --text-xl: 1.25rem;
    --text-2xl: 1.5rem;
    --text-3xl: 1.875rem;

    /* Font weights */
    --font-light: 300;
    --font-normal: 400;
    --font-medium: 500;
    --font-semibold: 600;
    --font-bold: 700;

    /* Line heights */
    --leading-tight: 1.25;
    --leading-normal: 1.5;
    --leading-relaxed: 1.625;

    /* Colors */
    --color-text: #2c3e50;
    --color-text-light: #6c757d;
    --color-link: #3498db;
    --color-link-hover: #2980b9;

    /* Subtle enhancements */
    --radius-sm: 4px;
    --transition: 0.2s ease-in-out;
}

/* Enhanced body typography */
body {
    font-family: var(--font-primary) !important;
    font-weight: var(--font-normal);
    line-height: var(--leading-normal);
    color: var(--color-text);
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
}

/* Modern heading styles */
h1, h2, h3, h4, h5, h6,
.mw-body-content h1, .mw-body-content h2, .mw-body-content h3,
.mw-body-content h4, .mw-body-content h5, .mw-body-content h6 {
    font-family: var(--font-primary) !important;
    font-weight: var(--font-semibold) !important;
    line-height: var(--leading-tight) !important;
    color: var(--color-text) !important;
}

h1, .mw-body-content h1 { font-size: var(--text-3xl) !important; }
h2, .mw-body-content h2 { font-size: var(--text-2xl) !important; }
h3, .mw-body-content h3 { font-size: var(--text-xl) !important; }
h4, .mw-body-content h4 { font-size: var(--text-lg) !important; }
h5, .mw-body-content h5 { font-size: var(--text-base) !important; }
h6, .mw-body-content h6 { font-size: var(--text-sm) !important; }

/* Enhanced links */
a {
    color: var(--color-link);
    transition: color var(--transition);
}

a:hover {
    color: var(--color-link-hover);
}

/* Modern code styling */
code, pre, kbd, samp, tt,
.mw-code {
    font-family: var(--font-mono) !important;
    font-size: var(--text-sm);
}

/* Enhanced paragraphs */
p {
    line-height: var(--leading-relaxed);
}

/* Modern navigation styling */
.mw-portlet h3 {
    font-family: var(--font-primary) !important;
    font-weight: var(--font-semibold) !important;
    font-size: var(--text-sm) !important;
    text-transform: uppercase;
    letter-spacing: 0.05em;
    color: var(--color-text-light) !important;
}

.mw-portlet ul li a {
    font-family: var(--font-primary) !important;
    font-size: var(--text-sm);
    transition: all var(--transition);
}

/* Enhanced form elements */
input, textarea, select {
    font-family: var(--font-primary) !important;
    border-radius: var(--radius-sm);
    transition: border-color var(--transition);
}

/* Enhanced buttons */
button, .mw-ui-button {
    font-family: var(--font-primary) !important;
    font-weight: var(--font-medium);
    border-radius: var(--radius-sm);
    transition: all var(--transition);
}

/* Responsive typography */
@media (max-width: 768px) {
    :root {
        --text-3xl: 1.5rem;
        --text-2xl: 1.25rem;
        --text-xl: 1.125rem;
    }
}

/* ===== ORIGINAL MEDIAWIKI STYLES ===== */
/* CSS placed here will be applied to all skins */
/*
 * This is the CSS common to all desktop skins on en.Wikipedia.
 * Styling inside .mw-parser-output should generally use TemplateStyles.
 */
/* Reset italic styling set by user agent */
cite,
dfn {
	font-style: inherit;
}

/* Straight quote marks for <q> */
q {
	quotes: '"' '"' "'" "'";
}

/* Avoid collision of blockquote with floating elements by swapping margin and padding */
blockquote {
	overflow: hidden;
	margin: 1em 0;
	padding: 0 40px;
}

/* Consistent size for <small>, <sub> and <sup> */
small {
	font-size: 85%;
}

.mw-body-content sub,
.mw-body-content sup {
	font-size: 80%;
}

/* Same spacing for indented and unindented paragraphs on talk pages */
.ns-talk .mw-body-content dd {
	margin-top: 0.4em;
	margin-bottom: 0.4em;
}

/* Reduce page jumps by hiding collapsed/dismissed content */
.client-js .collapsible:not( .mw-made-collapsible).collapsed > tbody > tr:not(:first-child),

/* Avoid FOUC/reflows on collapsed elements. */
/* This copies MediaWiki's solution for T42812 to apply to innercollapse/outercollapse (T325115). */
/* TODO: Use :is() selector at some reasonable future when support is good for Most Clients */
/* Reference: https://gerrit.wikimedia.org/g/mediawiki/core/+/ecda06cb2aef55b77c4b4d7ecda492d634419ead/resources/src/jquery/jquery.makeCollapsible.styles.less#75 */
.client-js .outercollapse .innercollapse.mw-collapsible:not( .mw-made-collapsible ) > p,
.client-js .outercollapse .innercollapse.mw-collapsible:not( .mw-made-collapsible ) > table,
.client-js .outercollapse .innercollapse.mw-collapsible:not( .mw-made-collapsible ) > thead + tbody,
.client-js .outercollapse .innercollapse.mw-collapsible:not( .mw-made-collapsible ) tr:not( :first-child ),
.client-js .outercollapse .innercollapse.mw-collapsible:not( .mw-made-collapsible ) .mw-collapsible-content,

/* Hide charinsert base for those not using the gadget */
#editpage-specialchars {
	display: none;
}

/* Make the list of references smaller
 * Keep in sync with Template:Refbegin/styles.css
 * And Template:Reflist/styles.css
 */
ol.references {
	font-size: 90%;
	margin-bottom: 0.5em;
}

/* Cite customizations for Parsoid
 * Once everything uses the one true parser these are just customizations
 */
span[ rel="mw:referencedBy" ] {
	counter-reset: mw-ref-linkback 0;
}

span[ rel='mw:referencedBy' ] > a::before {
	content: counter( mw-ref-linkback, lower-alpha );
	font-size: 80%;
	font-weight: bold;
	font-style: italic;
}

a[ rel="mw:referencedBy" ]::before {
	font-weight: bold;
	content: "^";
}

span[ rel="mw:referencedBy" ]::before {
	content: "^ ";
}

.mw-ref > a[data-mw-group=lower-alpha]::after {
	content: '[' counter( mw-Ref, lower-alpha ) ']';
}

.mw-ref > a[data-mw-group=upper-alpha]::after {
	content: '[' counter( mw-Ref, upper-alpha ) ']';
}

.mw-ref > a[data-mw-group=decimal]::after {
	content: '[' counter( mw-Ref, decimal ) ']';
}

.mw-ref > a[data-mw-group=lower-roman]::after {
	content: '[' counter( mw-Ref, lower-roman ) ']';
}

.mw-ref > a[data-mw-group=upper-roman]::after {
	content: '[' counter( mw-Ref, upper-roman ) ']';
}

.mw-ref > a[data-mw-group=lower-greek]::after {
	content: '[' counter( mw-Ref, lower-greek ) ']';
}

