		}
	}

	/**
	 * WikiMiniAtlas
	 *
	 * Description: WikiMiniAtlas is a popup click and drag world map.
	 *              This script causes all of our coordinate links to display the WikiMiniAtlas popup button.
	 *              The script itself is located on the Meta-Wiki because it is used by many projects.
	 *              See [[Meta:WikiMiniAtlas]] for more information.
	 * Note - use of this service is recommended to be replaced with mw:Help:Extension:Kartographer
	 */
	$( function () {
		var requireWikiminiatlas = $( 'a.external.text[href*="geohack"]' ).length || $( 'div.kmldata' ).length;
		if ( requireWikiminiatlas ) {
			mw.loader.load( '//meta.wikimedia.org/w/index.php?title=MediaWiki:Wikiminiatlas.js&action=raw&ctype=text/javascript' );
		}
	} );

	/**
	 * Collapsible tables; reimplemented with mw-collapsible
	 * Styling is also in place to avoid FOUC
	 *
	 * Allows tables to be collapsed, showing only the header. See [[Help:Collapsing]].
	 * @version 3.0.0 (2018-05-20)
	 * @source https://www.mediawiki.org/wiki/MediaWiki:Gadget-collapsibleTables.js
	 * @author [[User:R. Koot]]
	 * @author [[User:Krinkle]]
	 * @author [[User:TheDJ]]
	 * @deprecated Since MediaWiki 1.20: Use class="mw-collapsible" instead which
	 * is supported in MediaWiki core. Shimmable since MediaWiki 1.32
	 *
	 * @param {jQuery} $content
	 */
	function makeCollapsibleMwCollapsible( $content ) {
		var $tables = $content
			.find( 'table.collapsible:not(.mw-collapsible)' )
			.addClass( 'mw-collapsible' );

		$.each( $tables, function ( index, table ) {
			// mw.log.warn( 'This page is using the deprecated class collapsible. Please replace it with mw-collapsible.');
			if ( $( table ).hasClass( 'collapsed' ) ) {
				$( table ).addClass( 'mw-collapsed' );
				// mw.log.warn( 'This page is using the deprecated class collapsed. Please replace it with mw-collapsed.');
			}
		} );
		if ( $tables.length > 0 ) {
			mw.loader.using( 'jquery.makeCollapsible' ).then( function () {
				$tables.makeCollapsible();
			} );
		}
	}
	mw.hook( 'wikipage.content' ).add( makeCollapsibleMwCollapsible );

	/**
	 * Add support to mw-collapsible for autocollapse, innercollapse and outercollapse
	 *
	 * Maintainers: TheDJ
	 */
	function mwCollapsibleSetup( $collapsibleContent ) {
		var $element,
			$toggle,
			autoCollapseThreshold = 2;
		$.each( $collapsibleContent, function ( index, element ) {
			$element = $( element );
			if ( $element.hasClass( 'collapsible' ) ) {
				$element.find( 'tr:first > th:first' ).prepend( $element.find( 'tr:first > * > .mw-collapsible-toggle' ) );
			}
			if ( $collapsibleContent.length >= autoCollapseThreshold && $element.hasClass( 'autocollapse' ) ) {
				$element.data( 'mw-collapsible' ).collapse();
			} else if ( $element.hasClass( 'innercollapse' ) ) {
				if ( $element.parents( '.outercollapse' ).length > 0 ) {
					$element.data( 'mw-collapsible' ).collapse();
				}
			}
			// because of colored backgrounds, style the link in the text color
			// to ensure accessible contrast
			$toggle = $element.find( '.mw-collapsible-toggle' );
			if ( $toggle.length ) {
				// Make the toggle inherit text color (Updated for T333357 2023-04-29)
				if ( $toggle.parent()[ 0 ].style.color ) {
					$toggle.css( 'color', 'inherit' );
					$toggle.find( '.mw-collapsible-text' ).css( 'color', 'inherit' );
				}
			}
		} );
	}

	mw.hook( 'wikipage.collapsibleContent' ).add( mwCollapsibleSetup );

	/**
	 * Magic editintros ****************************************************
	 *
	 * Description: Adds editintros on disambiguation pages and BLP pages.
	 * Maintainers: [[User:RockMFR]]
	 *
	 * @param {string} name
	 */
	function addEditIntro( name ) {
		$( '.mw-editsection, #ca-edit, #ca-ve-edit' ).find( 'a' ).each( function ( i, el ) {
			el.href = $( this ).attr( 'href' ) + '&editintro=' + name;
		} );
	}

	if ( mw.config.get( 'wgNamespaceNumber' ) === 0 ) {
		$( function () {
			if ( document.getElementById( 'disambigbox' ) ) {
				addEditIntro( 'Template:Disambig_editintro' );
			}
		} );

		$( function () {
			var cats = mw.config.get( 'wgCategories' );
			if ( !cats ) {
				return;
			}
			if ( $.inArray( 'Living people', cats ) !== -1 || $.inArray( 'Possibly living people', cats ) !== -1 ) {
				addEditIntro( 'Template:BLP_editintro' );
			}
		} );
	}

		// Avantpedia Main JavaScript

	document.addEventListener('DOMContentLoaded', function() {
	    // Initialize all functionality
	    initializeSearch();
	    initializeSmoothScrolling();
	    initializeButtonStates();
	    initializeTableOfContents();
	    initializeAccessibility();
	    initializeThemeToggle();
	    initializeMobileNavigation();
	});

	// Search functionality
	function initializeSearch() {
	    const searchInput = document.querySelector('.search-input');
	    if (!searchInput) return;

	    // Handle search on Enter key
	    searchInput.addEventListener('keypress', function(e) {
	        if (e.key === 'Enter') {
	            performSearch(this.value.trim());
	        }
	    });

	    // Add search suggestions (basic implementation)
	    searchInput.addEventListener('input', function() {
	        const query = this.value.trim();
	        if (query.length > 2) {
	            showSearchSuggestions(query);
	        } else {
	            hideSearchSuggestions();
	        }
	    });
	}

	function performSearch(query) {
	    if (query) {
	        // For MediaWiki, redirect to search page
	        window.location.href = `Special:Search?search=${encodeURIComponent(query)}`;
	    }
	}

	function showSearchSuggestions(query) {
	    // Basic search suggestions - in a real implementation, this would query the wiki
	    const suggestions = [
	        'Legion of Astoria',
	        'Republic of Perasta',
	        'Solara',
	        'Union of Zhensanov',
	        'Dracoist Malonia',
	        'Orinian Empire',
	        'Federation of Vinterholm'
	    ].filter(item => item.toLowerCase().includes(query.toLowerCase()));

	    if (suggestions.length > 0) {
	        createSuggestionDropdown(suggestions);
	    }
	}

	function createSuggestionDropdown(suggestions) {
	    const searchContainer = document.querySelector('.nav-search');
	    let dropdown = document.querySelector('.search-suggestions');

	    if (!dropdown) {
	        dropdown = document.createElement('div');
	        dropdown.className = 'search-suggestions';
	        dropdown.style.cssText = `
	            position: absolute;
	            top: 100%;
	            left: 0;
	            right: 0;
	            background: white;
	            border: 1px solid #ddd;
	            border-radius: 5px;
	            box-shadow: 0 4px 8px rgba(0,0,0,0.1);
	            z-index: 1000;
	            max-height: 200px;
	            overflow-y: auto;
	        `;
	        searchContainer.appendChild(dropdown);
	    }

	    dropdown.innerHTML = suggestions.map(suggestion => 
	        `<div class="suggestion-item" style="padding: 0.5rem; cursor: pointer; border-bottom: 1px solid #eee;" 
	         onclick="selectSuggestion('${suggestion}')">${suggestion}</div>`
	    ).join('');
	}

	function selectSuggestion(suggestion) {
	    document.querySelector('.search-input').value = suggestion;
	    hideSearchSuggestions();
	    performSearch(suggestion);
	}

	function hideSearchSuggestions() {
	    const dropdown = document.querySelector('.search-suggestions');
	    if (dropdown) {
	        dropdown.remove();
	    }
	}

	// Smooth scrolling for anchor links
	function initializeSmoothScrolling() {
	    document.querySelectorAll('a[href^="#"]').forEach(anchor => {
	        anchor.addEventListener('click', function (e) {
	            e.preventDefault();
	            const target = document.querySelector(this.getAttribute('href'));
	            if (target) {
	                target.scrollIntoView({
	                    behavior: 'smooth',
	                    block: 'start'
	                });

	                // Update URL without jumping
	                history.pushState(null, null, this.getAttribute('href'));
	            }
	        });
	    });
	}

	// Button loading states
	function initializeButtonStates() {
	    document.querySelectorAll('.btn').forEach(btn => {
	        btn.addEventListener('click', function(e) {
	            if (!this.href.startsWith('#') && !this.href.includes('javascript:')) {
	                const originalContent = this.innerHTML;
	                this.style.opacity = '0.7';
	                this.innerHTML = '<i class="fas fa-spinner fa-spin"></i> Loading...';

	                // Reset after a delay if still on page
	                setTimeout(() => {
	                    if (this.innerHTML.includes('Loading...')) {
	                        this.innerHTML = originalContent;
	                        this.style.opacity = '1';
	                    }
	                }, 3000);
	            }
	        });
	    });
	}

	// Table of Contents functionality
	function initializeTableOfContents() {
	    const toc = document.querySelector('.toc');
	    if (!toc) return;

	    // Highlight current section in TOC
	    const sections = document.querySelectorAll('section[id]');
	    const tocLinks = document.querySelectorAll('.toc-list a');

	    function updateTOCHighlight() {
	        let current = '';
	        sections.forEach(section => {
	            const rect = section.getBoundingClientRect();
	            if (rect.top <= 100) {
	                current = section.id;
	            }
	        });

	        tocLinks.forEach(link => {
	            link.classList.remove('active');
	            if (link.getAttribute('href') === `#${current}`) {
	                link.classList.add('active');
	                link.style.color = 'var(--primary-blue)';
	                link.style.fontWeight = '600';
	            } else {
	                link.style.color = '';
	                link.style.fontWeight = '';
	            }
	        });
	    }

	    window.addEventListener('scroll', updateTOCHighlight);
	    updateTOCHighlight(); // Initial call
	}

	// Accessibility improvements
	function initializeAccessibility() {
	    // Add skip link
	    const skipLink = document.createElement('a');
	    skipLink.href = '#main';
	    skipLink.textContent = 'Skip to main content';
	    skipLink.className = 'skip-link';
	    skipLink.style.cssText = `
	        position: absolute;
	        top: -40px;
	        left: 6px;
	        background: var(--primary-blue);
	        color: white;
	        padding: 8px;
	        text-decoration: none;
	        border-radius: 4px;
	        z-index: 1000;
	        transition: top 0.3s;
	    `;

	    skipLink.addEventListener('focus', function() {
	        this.style.top = '6px';
	    });

	    skipLink.addEventListener('blur', function() {
	        this.style.top = '-40px';
	    });

	    document.body.insertBefore(skipLink, document.body.firstChild);

	    // Improve keyboard navigation
	    document.addEventListener('keydown', function(e) {
	        // ESC key closes search suggestions
	        if (e.key === 'Escape') {
	            hideSearchSuggestions();
	        }

	        // Tab navigation improvements
	        if (e.key === 'Tab') {
	            document.body.classList.add('keyboard-navigation');
	        }
	    });

	    document.addEventListener('mousedown', function() {
	        document.body.classList.remove('keyboard-navigation');
	    });
	}

	// Theme toggle functionality (for future dark mode)
	function initializeThemeToggle() {
	    // Check for saved theme preference
	    const savedTheme = localStorage.getItem('avantpedia-theme');
	    if (savedTheme) {
	        document.documentElement.setAttribute('data-theme', savedTheme);
	    }

	    // Create theme toggle button (hidden for now, can be enabled later)
	    const themeToggle = document.createElement('button');
	    themeToggle.innerHTML = '<i class="fas fa-moon"></i>';
	    themeToggle.className = 'theme-toggle';
	    themeToggle.style.cssText = `
	        display: none; /* Hidden for now */
	        position: fixed;
	        bottom: 20px;
	        right: 20px;
	        background: var(--primary-blue);
	        color: white;
	        border: none;
	        border-radius: 50%;
	        width: 50px;
	        height: 50px;
	        cursor: pointer;
	        box-shadow: 0 4px 8px rgba(0,0,0,0.2);
	        z-index: 1000;
	    `;

	    themeToggle.addEventListener('click', function() {
	        const currentTheme = document.documentElement.getAttribute('data-theme');
	        const newTheme = currentTheme === 'dark' ? 'light' : 'dark';

	        document.documentElement.setAttribute('data-theme', newTheme);
	        localStorage.setItem('avantpedia-theme', newTheme);

	        this.innerHTML = newTheme === 'dark' ? '<i class="fas fa-sun"></i>' : '<i class="fas fa-moon"></i>';
	    });

	    document.body.appendChild(themeToggle);
	}

	// Utility functions
	function debounce(func, wait) {
	    let timeout;
	    return function executedFunction(...args) {
	        const later = () => {
	            clearTimeout(timeout);
	            func(...args);
	        };
	        clearTimeout(timeout);
	        timeout = setTimeout(later, wait);
	    };
	}

	// Performance monitoring
	function initializePerformanceMonitoring() {
	    if ('performance' in window) {
	        window.addEventListener('load', function() {
	            setTimeout(function() {
	                const perfData = performance.getEntriesByType('navigation')[0];
	                console.log('Page load time:', perfData.loadEventEnd - perfData.loadEventStart, 'ms');
	            }, 0);
	        });
	    }
	}

	// Initialize performance monitoring
	initializePerformanceMonitoring();

	// Mobile Navigation
	function initializeMobileNavigation() {
	    const navToggle = document.querySelector('.nav-toggle');
	    const navMenu = document.querySelector('.nav-menu');

	    if (!navToggle || !navMenu) return;

	    navToggle.addEventListener('click', function() {
	        const isExpanded = this.getAttribute('aria-expanded') === 'true';

	        this.setAttribute('aria-expanded', !isExpanded);
	        navMenu.classList.toggle('active');

	        // Prevent body scroll when menu is open
	        document.body.style.overflow = !isExpanded ? 'hidden' : '';
	    });

	    // Close menu when clicking outside
	    document.addEventListener('click', function(e) {
	        if (!navToggle.contains(e.target) && !navMenu.contains(e.target)) {
	            navToggle.setAttribute('aria-expanded', 'false');
	            navMenu.classList.remove('active');
	            document.body.style.overflow = '';
	        }
	    });

	    // Close menu when pressing Escape
	    document.addEventListener('keydown', function(e) {
	        if (e.key === 'Escape' && navMenu.classList.contains('active')) {
	            navToggle.setAttribute('aria-expanded', 'false');
	            navMenu.classList.remove('active');
	            document.body.style.overflow = '';
	            navToggle.focus();
	        }
	    });

	    // Close menu when clicking on nav links
	    const navLinks = document.querySelectorAll('.nav-links a');
	    navLinks.forEach(link => {
	        link.addEventListener('click', function() {
	            navToggle.setAttribute('aria-expanded', 'false');
	            navMenu.classList.remove('active');
	            document.body.style.overflow = '';
	        });
	    });
	}

	// Export functions for potential external use
	window.AvantpediaJS = {
	    performSearch,
	    showSearchSuggestions,
	    hideSearchSuggestions
	};

	/* End of mw.loader.using callback */
} );
