ates = <!-- Coordinates for capital, using {{tl|coord}} --> |largest_city = Yeong-wonhan |largest_settlement_type = <!--Type of settlement if largest settlement not a city--> |largest_settlement = <!--Name of largest settlement--> |official_languages = [[Wikipedia:Korean language|Hyeonsu language]] |national_languages = <!--Country/territory-wide languages recognised but not necessarily in country/territory-wide law, etc--> |regional_languages = <!--Languages recognised or associated with particular regions within the country/territory--> |languages_type = <!--Use to specify a further type of language, if not official, national or regional--> |languages = <!--Languages of the further type--> |languages_sub = <!--Is this further type of language a sub-item of the previous non-sub type? ("yes" or "no")--> |languages2_type = <!--Another further type of language--> |languages2 = <!--Languages of this second further type--> |languages2_sub = <!--Is the second alternative type of languages a sub-item of the previous non-sub type? ("yes" or "no")--> |ethnic_groups = <!--List/breakdown of ethnic groups within the country/territory--> |ethnic_groups_year = <!--Year of ethnic groups data (if provided)--> |ethnic_groups_ref = <!--(for any ref/s to associate with ethnic groups data)--> |religion = [[Wikipedia:Korean Buddhism|Hyeosu Buddhism]] |religion_year = <!--Year of religion data (if provided)--> |religion_ref = <!--(for any ref/s to associate with religion data)--> |demonym = <!--Term/s describing those associated with the country/territory (e.g. "Belgian" for the country Belgium)--> |government_type = Constitutional Monarchy |leader_title1 = Emperor |leader_name1 = Ilseong Heung-an |leader_title2 = Prime Minister |leader_name2 = Joon Seomun |leader_title14 = <!--(up to 14 distinct leaders may be included)--> |leader_name14 = |legislature = <!--Name of the country/territory's governing body, e.g. "Parliament", "Congress", etc--> |upper_house = <!--Name of governing body's