/* {{pp|small=yes}} */
.reflist {
	margin-bottom: 0.5em;
	list-style-type: decimal;
}

@media screen {
	/* can we remove the font size declarations? .references gets a font-size in
	 * common.css that is always 90, and there is nothing else in reflist out in
	 * the wild. May affect column sizes.
	 */
	 /* make smaller only on screens */
	.reflist {
		font-size: 90%;        /* Default font-size */
	}
}

.reflist .references {
	font-size: 100%;           /* Reset font-size when nested in .reflist */
	margin-bottom: 0;          /* Avoid double margin when nested in .reflist */
	list-style-type: inherit;  /* Enable custom list style types */
}

/* columns-2 and columns-3 are legacy for "2 or more" column view from when the
 * template was implemented with column-count.
 */
.reflist-columns-2 {
	column-width: 30em;
}

.reflist-columns-3 {
	column-width: 25em;
}

/* Reset top margin for lists embedded in columns */
.reflist-columns {
	margin-top: 0.3em;
}

.reflist-columns ol {
	margin-top: 0;
}

/* Avoid elements breaking between columns */
.reflist-columns li {
	page-break-inside: avoid; /* Removed from CSS in favor of break-inside c. 2020 */
	break-inside: avoid-column;
}

.reflist-upper-alpha {
	list-style-type: upper-alpha;
}

.reflist-upper-roman {
	list-style-type: upper-roman;
}

.reflist-lower-alpha {
	list-style-type: lower-alpha;
}

.reflist-lower-greek {
	list-style-type: lower-greek;
}

.reflist-lower-roman {
	list-style-type: lower-roman;
}

/* {{pp|small=yes}} */
.reflist {
	margin-bottom: 0.5em;
	list-style-type: decimal;
}

@media screen {
	/* can we remove the font size declarations? .references gets a font-size in
	 * common.css that is always 90, and there is nothing else in reflist out in
	 * the wild. May affect column sizes.
	 */
	 /* make smaller only on screens */
	.reflist {
		font-size: 90%;        /* Default font-size */
	}
}

.reflist .references {
	font-size: 100%;           /* Reset font-size when nested in .reflist */
	margin-bottom: 0;          /* Avoid double margin when nested in .reflist */
	list-style-type: inherit;  /* Enable custom list style types */
}

/* columns-2 and columns-3 are legacy for "2 or more" column view from when the
 * template was implemented with column-count.
 */
.reflist-columns-2 {
	column-width: 30em;
}

.reflist-columns-3 {
	column-width: 25em;
}

/* Reset top margin for lists embedded in columns */
.reflist-columns {
	margin-top: 0.3em;
}

.reflist-columns ol {
	margin-top: 0;
}

/* Avoid elements breaking between columns */
.reflist-columns li {
	page-break-inside: avoid; /* Removed from CSS in favor of break-inside c. 2020 */
	break-inside: avoid-column;
}

.reflist-upper-alpha {
	list-style-type: upper-alpha;
}

.reflist-upper-roman {
	list-style-type: upper-roman;
}

.reflist-lower-alpha {
	list-style-type: lower-alpha;
}

.reflist-lower-greek {
	list-style-type: lower-greek;
}

.reflist-lower-roman {
	list-style-type: lower-roman;
}

/* {{pp-template}} */
.treeview ul {
	padding: 0;
	margin: 0;
}

.treeview li {
	padding: 0;
	margin: 0;
	list-style-type: none;
	list-style-image: none;
}

.treeview li li {
	background: url("https://upload.wikimedia.org/wikipedia/commons/f/f2/Treeview-grey-line.png") no-repeat 0 -2981px;
	/* @noflip */
	padding-left: 21px;
	text-indent: 0.3em;
}

.treeview li li:last-child {
	background-position: 0 -5971px
}

/* first line here deals with new situation after RemexHTML switch,
 * where emptyline cause the first child to become the 2nd child. Such a mess
 */
.treeview li.emptyline > ul > .mw-empty-elt:first-child + .emptyline,
.treeview li.emptyline > ul > li:first-child {
	background-position: 0 9px
}

